CREATE OR REPLACE PROCEDURE calculate_apt()
LANGUAGE plpgsql
AS $$
BEGIN
    -- Add apt column if it doesn't exist
    ALTER TABLE cases ADD COLUMN IF NOT EXISTS apt numeric;

    -- Update APT for all cases where both dates are available
    UPDATE cases 
    SET apt = CAST(
        (CAST(decisionday AS date) - CAST(recvday AS date)) AS numeric
    )
    WHERE decisionday IS NOT NULL AND recvday IS NOT NULL;
END;
$$;

