CREATE OR REPLACE PROCEDURE calculate_apt()
LANGUAGE plpgsql
AS $$
DECLARE
    r RECORD;
BEGIN
    ALTER TABLE cases ADD COLUMN IF NOT EXISTS apt numeric;
    FOR r IN SELECT filekey, decisionday, recvday FROM cases WHERE decisionday IS NOT NULL AND recvday IS NOT NULL LOOP
        UPDATE cases SET apt = (CAST(r.decisionday AS date) - CAST(r.recvday AS date))::numeric WHERE filekey = r.filekey;
    END LOOP;
END;
$$;

CALL calculate_apt();

