LANGUAGE plpgsql
AS $$
BEGIN
    ALTER TABLE cases ADD COLUMN IF NOT EXISTS apt numeric;
    UPDATE cases SET apt = EXTRACT(EPOCH FROM (CAST(decisionday AS timestamp) - CAST(recvday AS timestamp))) / 86400
    WHERE decisionday IS NOT NULL AND recvday IS NOT NULL;
END;
