CREATE OR REPLACE FUNCTION calculate_apt(p_filekey text) RETURNS numeric AS $$
DECLARE
    v_recv date;
    v_decision date;
BEGIN
    SELECT CAST(recvday AS date), CAST(decisionday AS date) INTO v_recv, v_decision 
    FROM cases WHERE filekey = p_filekey;
    RETURN (v_decision - v_recv)::numeric;
END;
$$ LANGUAGE plpgsql;

