END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION calculate_apt() RETURNS TABLE(filekey text, apt numeric) AS $$
BEGIN
    RETURN QUERY
    SELECT c.filekey, (CAST(c.decisionday AS date) - CAST(c.recvday AS date))::numeric
    FROM cases c
    WHERE c.decisionday IS NOT NULL AND c.recvday IS NOT NULL;
END;
$$ LANGUAGE plpgsql;
